// Data-plane glue: converts Swift values into the pointer+length
// arguments of the C++ wrappers declared in the bridge module's
// rust_bridge.h (generated by build.rs), so no imported C++ template
// types — rust::Slice — leak past this file. Pure-primitive events
// (`on_response_head`, `on_done`) are called directly.

import Foundation
import monet_urlsession_bridge

/// Builds a String from a pointer+length across the control plane.
@inline(__always)
func bridgeString(_ ptr: UnsafePointer<UInt8>, _ len: Int) -> String {
  String(decoding: UnsafeBufferPointer(start: ptr, count: len), as: UTF8.self)
}

/// Sends one response header event.
@inline(__always)
func notifyHeader(_ id: UInt64, name: String, value: String) {
  let name = Array(name.utf8)
  let value = Array(value.utf8)
  guard !name.isEmpty, !value.isEmpty else { return }
  name.withUnsafeBufferPointer { nameBuf in
    value.withUnsafeBufferPointer { valueBuf in
      monet_on_header(
        id, nameBuf.baseAddress, nameBuf.count, valueBuf.baseAddress, valueBuf.count)
    }
  }
}

/// Sends the response head event; all headers for the response must
/// already have been sent (ordering contract in src/ffi.rs).
@inline(__always)
func notifyResponseHead(_ id: UInt64, status: Int) {
  on_response_head(id, UInt16(status))
}

/// Sends one body chunk. URLSession never delivers empty data events, so
/// the empty case is defensive only.
@inline(__always)
func notifyChunk(_ id: UInt64, data: Data) {
  guard !data.isEmpty else { return }
  data.withUnsafeBytes { (raw: UnsafeRawBufferPointer) in
    monet_on_chunk(id, raw.baseAddress?.assumingMemoryBound(to: UInt8.self), raw.count)
  }
}

/// Sends an informational redirect event.
@inline(__always)
func notifyRedirect(_ id: UInt64, location: String) {
  let location = Array(location.utf8)
  guard !location.isEmpty else { return }
  location.withUnsafeBufferPointer { buf in
    monet_on_redirect(id, buf.baseAddress, buf.count)
  }
}

/// Sends the terminal success event.
@inline(__always)
func notifyDone(_ id: UInt64) {
  on_done(id)
}

/// Sends the terminal error event. `code` is the NSError code.
@inline(__always)
func notifyError(_ id: UInt64, code: Int, message: String) {
  let message = Array(message.utf8)
  message.withUnsafeBufferPointer { buf in
    monet_on_error(id, Int32(code), buf.baseAddress, buf.count)
  }
}
